        return f"{degrees}d{minutes}'{sec_str}\"{suffix}"
    else:
        # forced: minutes and seconds two-digit, seconds fixed res decimals (zero padded)
        if res > 0:
            sec_str = f"{sec_int:02d}.{sec_frac:0{res}d}"
