_FMT_VALID_RE = re.compile(r"^%[0-9.+]*[fFeEgG]$")
def valid_format(fmt):
    if fmt is None: return False
    return bool(_FMT_VALID_RE.match(fmt))

def format_number(fmt, val):
    """Format with restricted C format. Returns '' for malformed-but-validated specs like reference."""
    if fmt is None:
        fmt = "%.2f"
    # parse strict: % [+] [0] [width] [. [prec]] conv
    if not fmt.startswith("%") or len(fmt) < 2:
        return ""
    conv = fmt[-1]
    if conv not in "fFeEgG":
        return ""
    body = fmt[1:-1]
    i = 0
    plus = False
    zero = False
    if i < len(body) and body[i] == "+":
        plus = True; i += 1
    if i < len(body) and body[i] == "0":
        zero = True; i += 1
    # width digits
    ws = i
    while i < len(body) and body[i].isdigit():
        i += 1
    width_str = body[ws:i]
    prec_str = None
    if i < len(body) and body[i] == ".":
        i += 1
        ps = i
        while i < len(body) and body[i].isdigit():
            i += 1
        prec_str = body[ps:i]
        if prec_str == "":
            prec_str = "0"
    if i != len(body):
        return ""
    width = int(width_str) if width_str else 0
    prec = int(prec_str) if prec_str is not None else None
    if width > 100000 or (prec is not None and prec > 100000):
        return ""
    # build python format
    pyfmt = "%"
    if plus: pyfmt += "+"
    if zero: pyfmt += "0"
    if width_str: pyfmt += str(width)
    if prec_str is not None: pyfmt += "." + str(prec)
    pyfmt += conv
    try:
        return pyfmt % (val,)
    except Exception:
        return ""

