        dx=fx-x; dy=fy-y
        if abs(dx)<1e-9 and abs(dy)<1e-9: break
        h=1e-7
        fx1,fy1=fwd_tmerc(op,lam+h,phi,lam+op.lon0)
        fx2,fy2=fwd_tmerc(op,lam,phi+h,lam+op.lon0)
        j11=(fx1-fx)/h; j21=(fy1-fy)/h; j12=(fx2-fx)/h; j22=(fy2-fy)/h
        det=j11*j22-j12*j21
        if det==0: break
        lam+=(-dx*j22+dy*j12)/det
        phi+=(-j11*dy+j21*dx)/det
    return (lam,phi)

