        Y=N*math.cos(phi)*math.sin(lam)
        # false/units? cart ignores x0/k0 etc presumably
        return (X,Y)
    def inverse(self,x,y,raw=False):
        a=self.ell.a; es=self.ell.es; b=a*math.sqrt(1-es)
