    # initval examples epsg:3857, nad27:101, nad83:..., IGNF:..., epsg:...
    low=initval.lower()
    if low.startswith("epsg:"):
        # creates an operation which app rejects as nonangular input
        # But if code not exist, proj_create may fail first - probe later. We'll try create epsg op; if fails propagate? For known, mark nonangular.
        try:
            op=make_epsg_operation(initval.split(":",1)[1], None)
            op.kind="nonangular"
            op._force_nonangular=True
            return op
        except InitError as e:
            # Reference for +init=epsg:9999 ? probe later
            raise
    # named init files
    if ":" in initval:
        fname,key=initval.split(":",1)
        table=INIT_FILES.get(fname.lower())
        if table and key in table:
            # table value is list of +tokens
            base_params=ParamList(table[key])
            # merge: base plus other user params except init (user override names appended later - our get returns first, so put user first if override semantics? PROJ init: subsequent params can override? For old pj_init init expansion, params following init replace? We'll put user params first for get priority but order for verbose: base likely first. Minor.)
            merged_items=list(base_params.items)
            existing={n for n,v,r in merged_items}
            for n,v,r in params.items:
                if n=="init": continue
                if n not in existing:
                    merged_items.append((n,v,r))
                else:
                    # replace value of existing with user? Put user earlier by replacing
                    merged_items=[(n,v,r) if nn==n else (nn,vv,rr) for nn,vv,rr in merged_items]
            mp=ParamList([])
            mp.items=merged_items
            op=make_operation(mp)
            op._init_expansion=table[key]
            return op
        # Unknown init file/key: need approximate error. Reference likely proj_create fails with (?), see probes after CLI.
        raise init_error_unknown()
    raise init_error_unknown()

