def epsg_tokens(code):
    if 32601<=code<=32660:
        z=code-32600; return ["+proj=utm",f"+zone={z}","+ellps=WGS84"]
    if 32701<=code<=32760:
        z=code-32700; return ["+proj=utm",f"+zone={z}","+south","+ellps=WGS84"]
    if 25801<=code<=25860:
        # ETRS89 UTM zones 28-38 only real, but pattern could overmatch. Limit to known 25828-25838
        if 25828<=code<=25838:
            z=code-25800; return ["+proj=utm",f"+zone={z}","+ellps=GRS80"]
    if code in EPSG_TABLE:
        return list(EPSG_TABLE[code])
    return None

def make_epsg_operation(code_str, original):
    # code_str may contain version : etc
    m=re.fullmatch(r"(\d+)",code_str.strip())
    if not m:
        raise CrsError("proj_create: unrecognized format / unknown name\n","CRS is not parseable")
    code=int(m.group(1))
    toks=epsg_tokens(code)
    if toks is not None:
        op=make_operation(ParamList(toks))
        op._epsg_code=code
        op._epsg_tokens=toks
        return op
    if code in EPSG_GEOGRAPHIC:
        raise CrsError(None,"CRS must be projected")
    # Heuristic: many EPSG codes in 2xxxx etc ...
    raise CrsError(f"proj_create: crs not found: EPSG:{code}\n","CRS is not parseable")

def make_crs_operation(s):
    """Create op from first non-plus argument interpreted as CRS. Raises CrsError/InitError."""
    # EPSG patterns
    m=re.match(r"(?i)epsg:(\d+)$",s)
    if m:
        return make_epsg_operation(m.group(1),s)
    m=re.match(r"(?i)urn:ogc:def:crs:epsg::?(\d+)$",s)
    if m:
        return make_epsg_operation(m.group(1),s)
    m=re.match(r"(?i)urn:ogc:def:crs:epsg:[\d.]*:(\d+)$",s)
    if m:
        return make_epsg_operation(m.group(1),s)
    if re.match(r"(?i)urn:ogc:def:crs:ogc:1\.3:crs84$",s):
        raise CrsError(None,"CRS must be projected")
    # WKT - rudimentary
    if s.strip().upper().startswith(("PROJCS","PROJCRS","PROJECTEDCRS","PROJECTION")):
        op=make_wkt_operation(s)
        if op is not None:
            return op
        raise CrsError("proj_create: unrecognized format / unknown name\n","CRS is not parseable")
    if s.strip().upper().startswith(("GEOGCS","GEOGCRS","GEOGRAPHICCRS","GEODCRS")):
        raise CrsError(None,"CRS must be projected")
    if s.startswith("proj="):
        raise CrsError(None,"CRS must be projected")
    # Known geographic CRS names maybe
    if s in ("WGS 84","WGS84","NAD83","NAD27","ETRS89"):
        raise CrsError(None,"CRS must be projected")
    raise CrsError("proj_create: unrecognized format / unknown name\n","CRS is not parseable")

def make_wkt_operation(s):
    # Minimal WKT1 PROJCS parser: PROJECTION["Mercator"] etc and PARAMETER[...]
    # Extract projection name
    m=re.search(r'PROJECTION\s*\[\s*"([^"]+)"',s,re.I)
    if not m: return None
    pname=m.group(1).lower()
    proj_map={"mercator":"merc","transverse_mercator":"tmerc","lambert_conformal_conic":"lcc","lambert_conformal_conic_2sp":"lcc","albers_conic_equal_area":"aea","lambert_azimuthal_equal_area":"laea","stereographic":"stere","orthographic":"ortho","equirectangular":"eqc"}
    if pname not in proj_map: return None
    params={}
    for pm in re.finditer(r'PARAMETER\s*\[\s*"([^"]+)"\s*,\s*([-\d.]+)',s,re.I):
        params[pm.group(1).lower()]=pm.group(2)
    toks=[f"+proj={proj_map[pname]}"]
    # spheroid
    sm=re.search(r'SPHEROID\s*\[\s*"[^"]*"\s*,\s*([-\d.]+)\s*,\s*([-\d.]+)',s,re.I)
    if sm:
        toks.append(f"+a={sm.group(1)}")
        if float(sm.group(2))!=0: toks.append(f"+rf={sm.group(2)}")
    def add(wkt,proj):
        if wkt in params: toks.append(f"+{proj}={params[wkt]}")
    add("central_meridian","lon_0"); add("longitude_of_center","lon_0"); add("latitude_of_origin","lat_0"); add("latitude_of_center","lat_0")
    add("standard_parallel_1","lat_1"); add("standard_parallel_2","lat_2"); add("scale_factor","k_0"); add("false_easting","x_0"); add("false_northing","y_0")
    # units?
    return make_operation(ParamList(toks))

