            if len(chunk)<16: break
            v1,v2=struct.unpack("<dd",chunk)
            count+=1
            process_coordinate(opts,op,out,v1,v2,"","",True)
        out.flush()
        return
    lineno=0
    # iterate lines as bytes, keep if file doesn't end with newline
    while True:
        raw=stream.readline()
        if not raw:
