        if opts.inverse:
            v1,e1=c_strtod(body,0)
            v2,e2=c_strtod(body,e1)
        else:
            v1,e1=dmstor(body,0)
            v2,e2=dmstor(body,e1)
        tail=body[e2:]
        echo=body[:e2]
        is_bin_out=opts.binary_out
        if opts.very:
            process_coordinate_V(opts,op,out,v1,v2,tail,display,lineno)
        else:
            process_coordinate(opts,op,out,v1,v2,echo,tail,is_bin_out)
    out.flush()

