def list_exit(opts_list_arg, arg, pos_in_arg, out):
    # arg is full option string e.g. -lP, pos index of 'l'
    if pos_in_arg+1>=len(arg):
        sub=""
    else:
        sub=arg[pos_in_arg+1]
    if sub=="" or sub=="p":
        out.write(LIST_P)
    elif sub=="e":
        out.write(LIST_E)
    elif sub=="u":
        out.write(LIST_U)
    elif sub=="P":
        out.write(LIST_P_EXT)
    elif sub=="=":
        name=arg[pos_in_arg+2:]
        meta=PROJ_META.get(name)
        if meta:
            out.write(f"{name:>9} : {meta['descr']}\n")
            for line in meta["lines"]:
                out.write(f"\t{line}\n")
    else:
        emess(1,f"invalid list option: l{sub}")
    out.flush()
    raise SystemExit(0)

def angular_flags(op):
    if getattr(op,"_force_nonangular",False):
        return (False,False)
    if op.kind=="angular_out":
        return (True,True)
    if op.kind=="nonangular":
        return (False,False)
    if isinstance(op,UnitConvertOperation):
        return (op.xy_in in UNITCONVERT_ANGULAR, op.xy_out in UNITCONVERT_ANGULAR)
    if isinstance(op,PipelineOperation):
        def step_flags(step_op,step_inv):
            if getattr(step_op,"_io_whatever",False):
                return None
            ain,aout=angular_flags(step_op)
            return (aout,ain) if step_inv else (ain,aout)
        fin=None; fout=None
        for so,si in op.steps:
            fl=step_flags(so,si)
            if fl is not None:
                fin=fl[0]; break
        for so,si in reversed(op.steps):
            fl=step_flags(so,si)
            if fl is not None:
                fout=fl[1]; break
        return (bool(fin) if fin is not None else False, bool(fout) if fout is not None else False)
    return (True,False)

def process_coordinate(opts, op, out, v1, v2, echo_str, tail_str, is_binary):
    """Process one coordinate in normal (non-V) mode. v1/v2 are parsed values before swap/scale."""
    scale=opts.scale
    # parse HUGE detection
    parse_huge = (v1==HUGE or v2==HUGE)
    a=v1; b=v2
    if opts.reverse_in:
        a,b=b,a
    factor_coord=(a,b)
    error=False
    err_log=None
    out1=out2=None
    geo=None
    if parse_huge:
        error=True
    else:
        try:
            if opts.inverse:
                ix=a/scale; iy=b/scale
                lam,phi=op.inverse(ix,iy)
                if lam==HUGE or phi==HUGE:
                    raise CoordError()
                geo=(lam,phi)
                # output order swap
                o1,o2=(phi,lam) if opts.reverse_out else (lam,phi)
                out1,out2=o1,o2
            else:
                x,y=op.forward(a,b)
                if x==HUGE or y==HUGE:
                    raise CoordError()
                geo=(a,b)
                x*=scale; y*=scale
                o1,o2=(y,x) if opts.reverse_out else (x,y)
                out1,out2=o1,o2
        except CoordError as ce:
            error=True
            if ce.log:
                eprint(ce.log+"\n")
        except Exception as ex:
            error=True
    # Factors -S
    factors_str=None
    if opts.factors:
        # compute using factor_coord as lam,phi
        try:
            if parse_huge:
                raise CoordError()
            f=compute_factors(op,factor_coord[0],factor_coord[1])
            factors_str=format_factors_S(f)
        except CoordError as ce:
            if ce.log:
                eprint(ce.log+"\n")
            factors_str="<* * * * * *>"
        except Exception:
            factors_str="<* * * * * *>"
    if is_binary:
        # binary output
        if error:
            out.write(struct.pack("<dd",HUGE,HUGE))
        else:
            out.write(struct.pack("<dd",float(out1),float(out2)))
        return
    # text output
    fmt=opts.fmt
    if error:
        if opts.emess is not None:
            core=opts.emess
            if opts.echo:
                line=f"{echo_str}\t{core}"
            else:
                line=core
            if factors_str is not None:
                line+=f"\t{factors_str}"
            line+=tail_str+"\n"
            out.write(line); return
        else:
            if opts.echo:
                line=f"{echo_str}\t*\t*"
            else:
                line="*\t*"
            if factors_str is not None:
                line+=f"\t{factors_str}"
            line+=tail_str+"\n"
            out.write(line); return
    # success
    if opts.inverse:
        # out1/out2 are lam/phi in output order (or swapped)
        if fmt is not None:
            s1=format_number(fmt,out1*RAD); s2=format_number(fmt,out2*RAD)
        else:
            # DMS, axis depends on which coordinate it is
            if not opts.reverse_out:
                s1=rtodms(out1,"E"); s2=rtodms(out2,"N")
            else:
                s1=rtodms(out1,"N"); s2=rtodms(out2,"E")
    else:
        use_fmt=fmt if fmt is not None else "%.2f"
        s1=format_number(use_fmt,out1); s2=format_number(use_fmt,out2)
    if opts.echo:
        line=f"{echo_str}\t{s1}\t{s2}"
    else:
        line=f"{s1}\t{s2}"
    if factors_str is not None:
        line+=f"\t{factors_str}"
    line+=tail_str+"\n"
    out.write(line)

def process_coordinate_V(opts, op, out, v1, v2, tail_str, filename_display, lineno):
    scale=opts.scale
    a=v1; b=v2
    if opts.reverse_in:
        a,b=b,a
    # geographic and projected coords
    lam=phi=x=y=None
    error=False; err_kind="domain"
    if v1==HUGE or v2==HUGE:
        error=True; err_kind="invalid"
    else:
        try:
            if opts.inverse:
                ix=a/scale; iy=b/scale
                lam,phi=op.inverse(ix,iy)
                if lam==HUGE or phi==HUGE: raise CoordError()
                x,y=ix,iy  # Easting/Northing are input values after scale (?) Observed -m2 inverse: Easting 500 for input1000 (yes divided)
                # Wait reverse_out -s in V inverse: observed Easting remained ix (1000), Northing iy, so -s ignored in V
            else:
                lam,phi=a,b
                x,y=op.forward(a,b)
                if x==HUGE or y==HUGE: raise CoordError()
                x*=scale; y*=scale
        except CoordError as ce:
            error=True
            if ce.log:
                eprint(ce.log+"\n")
                err_kind="invalid" if "Invalid" in ce.log else "domain"
            else:
                err_kind="domain"
        except Exception:
            error=True; err_kind="domain"
    if error:
        reason="Invalid coordinate" if err_kind=="invalid" else "Point outside of projection domain"
        eprint(f"{RELEASE}\n<{PROG}>: while processing file: {filename_display}, line {lineno}\n{reason}\n")
        return
    # factors at geographic
    try:
        f=compute_factors(op,lam,phi)
    except Exception as ex:
        # In reference, if factors fails? It might report Invalid coordinate. Treat as error above
        reason="Invalid coordinate"
        eprint(f"{RELEASE}\n<{PROG}>: while processing file: {filename_display}, line {lineno}\n{reason}\n")
        return
    if tail_str:
        out.write(tail_str+"\n")
    fmt_user=opts.fmt
    fmt_east=fmt_user if fmt_user is not None else ("%.3f" if opts.inverse else "%.2f")
    # Longitude/Latitude lines: rtodms uses DmsFmt current settings
    lon_str=rtodms(lam,"E"); lat_str=rtodms(phi,"N")
    out.write(f"Longitude: {lon_str} [ {'%.11g'%(lam*RAD)} ]\n")
    out.write(f"Latitude:  {lat_str} [ {'%.11g'%(phi*RAD)} ]\n")
    out.write(f"Easting (x):   {format_number(fmt_east,x)}\n")
    out.write(f"Northing (y):  {format_number(fmt_east,y)}\n")
    def errpct(v):
        return "%.4g"%(((v-1)*100),)
    out.write(f"Meridian scale (h) : {f.h:.8f}  ( {errpct(f.h)} % error )\n")
    out.write(f"Parallel scale (k) : {f.k:.8f}  ( {errpct(f.k)} % error )\n")
    out.write(f"Areal scale (s):     {f.s:.8f}  ( {errpct(f.s)} % error )\n")
    out.write(f"Angular distortion (w): {f.w:.3f}\n")
    out.write(f"Meridian/Parallel angle: {f.theta:.5f}\n")
    conv_str=rtodms(f.conv,"E")  # convergence rtodms without suffix? Observed "0d" and "4d39'59.181\"" - no E/W suffix!
    # rtodms for convergence in PROJ uses a version without hemisphere? Their code uses rtodms with sign? Let's strip suffix and handle sign
    # Our rtodms returns like 4d... "E or W for negative. Reference at negative convergence?
    # We'll generate custom:
    conv_str=dms_no_suffix(f.conv)
    out.write(f"Convergence : {conv_str} [ {f.conv*RAD:.8f} ]\n")
    out.write(f"Max-min (Tissot axis a-b) scale error: {f.a:.5f} {f.b:.5f}\n")
    out.write("\n")

def dms_no_suffix(rad):
    # Use rtodms logic but suffix omitted, sign? If negative, PROJ rtodms for convergence likely starts with '-'. We'll implement based on rtodms abs then prepend - if negative and nonzero.
    s=rtodms(abs(rad),"E")
    # strip trailing E
    if s.endswith("E"):
        s=s[:-1]
    if rad<0 and abs(rad)>0:
        # Does ref show -? Need test with a case negative convergence (tmerc west). We'll assume '-' prefix
        s="-"+s
    return s

