def process_stream(opts,op,out,stream,display):
    if opts.binary_in:
        data=stream.read()
        if data is None: data=b""
        count=0
        for off in range(0, len(data)-15, 16):
            chunk=data[off:off+16]
            if len(chunk)<16: break
            v1,v2=struct.unpack("<dd",chunk)
            count+=1
            process_coordinate(opts,op,out,v1,v2,"","",True)
        out.flush()
        return
    lineno=0
    # iterate lines as bytes, keep if file doesn't end with newline
    while True:
        raw=stream.readline()
        if not raw:
            break
        lineno+=1
        body=raw.decode("latin-1")
        if body.endswith("\n"):
            body=body[:-1]
        # tag check first char
        if body and body[0]==opts.tag:
            out.write(body+"\n")
