import math,subprocess,importlib.util
spec=importlib.util.spec_from_file_location("p","proj.py");m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
ell=m.Ellipsoid(*m.ELLIPSOIDS['GRS80'])
def trans(phi,kind):
 if kind=='geod':return phi
 if kind=='auth':return m.authalic_lat(phi,ell)
 if kind=='conf':return m.conformal_lat(phi,ell)
 if kind=='geoc':return math.atan((1-ell.es)*math.tan(phi))
 if kind=='rect':return m.meridional_arc(phi,ell)/m.meridional_arc(math.pi/2,ell)*math.pi/2
def cand(lon,lat,lon0,lat0,kind,radius):
 phi=trans(math.radians(lat),kind);phi0=trans(math.radians(lat0),kind);lam=math.radians(lon-lon0)
 den=math.sin(phi0)*math.sin(phi)+math.cos(phi0)*math.cos(phi)*math.cos(lam)
 return radius*math.cos(phi)*math.sin(lam)/den, radius*(math.cos(phi0)*math.sin(phi)-math.sin(phi0)*math.cos(phi)*math.cos(lam))/den
pts=[]
for lat0,lon0 in [(0,0),(20,5),(45,10),(-30,-20)]:
 for lon,lat in [(lon0+2,lat0+5),(10,10),(2,45)]:
  p=subprocess.run(["./executable","+proj=gnom",f"+lat_0={lat0}",f"+lon_0={lon0}"],input=f"{lon} {lat}\n".encode(),capture_output=True)
  if b'*' not in p.stdout:
   x,y=map(float,p.stdout.split());pts.append((lon,lat,lon0,lat0,x,y))
for kind in ['geod','auth','conf','geoc','rect']:
 for radius in [ell.a,6371007.181,ell.a*math.sqrt(1-ell.es)]:
  err=max(max(abs(cand(*pt[:4],kind,radius)[0]-pt[4]),abs(cand(*pt[:4],kind,radius)[1]-pt[5])) for pt in pts)
  rms=math.sqrt(sum((cand(*pt[:4],kind,radius)[0]-pt[4])**2+(cand(*pt[:4],kind,radius)[1]-pt[5])**2 for pt in pts)/len(pts))
  print(kind,radius,err,rms)
