def natural_spline_coeff(tab):
    n=len(tab); h=1.0
    # solve tridiagonal for second derivatives M
    # M0=Mn-1=0; for i 1..n-2: M_{i-1}+4M_i+M_{i+1}=6(tab[i-1]-2tab[i]+tab[i+1])/h^2
    import copy
    A=[[0.0]*(n) for _ in range(n)]; b=[0.0]*n
    A[0][0]=1; A[-1][-1]=1
    for i in range(1,n-1):
        A[i][i-1]=1; A[i][i]=4; A[i][i+1]=1; b[i]=6*(tab[i-1]-2*tab[i]+tab[i+1])
    # gaussian elimination
    for i in range(n):
        piv=A[i][i]
        for j in range(i,n): A[i][j]/=piv
        b[i]/=piv
        for k in range(n):
            if k!=i and A[k][i]!=0:
                factor=A[k][i]
                for j in range(i,n): A[k][j]-=factor*A[i][j]
                b[k]-=factor*b[i]
    return b
