def spline_eval(tab,M,idx):
    i=max(0,min(len(tab)-2,int(math.floor(idx)))); t=idx-i
    return ( (1-t)*tab[i]+t*tab[i+1] + t*(1-t)*((1-t)* 0 +0) ) # placeholder
def spline_nat(tab,M,idx):
    i=max(0,min(len(tab)-2,int(math.floor(idx)))); t=idx-i; h=1
    return ((1-t)**3)*0 + ( ( (1-t)*tab[i]+t*tab[i+1]) - (t*(1-t)/6)*((1-t)*0) )
# proper formula: S = ( (h-t)^3 M_i + t^3 M_{i+1})/(6h) + (y_i - M_i h^2/6)(h-t)/h + ...
def spline_nat2(tab,M,idx):
    i=max(0,min(len(tab)-2,int(math.floor(idx)))); t=idx-i
    return ((1-t)**3*M[i]+t**3*M[i+1])/6 + (tab[i]-M[i]/6)*(1-t)+(tab[i+1]-M[i+1]/6)*t
for name,fn in [('natural',lambda tab,M,idx: spline_nat2(tab,M,idx))]:
