    return (C*lam*(1-abs(phi)/math.pi), C*phi)
def inv_eck1(op,x,y):
    C=0.9213177319235614*op.ell.a*op.k0
    phi=y/C
    denom=C*(1-abs(phi)/math.pi)
    return (x/denom if denom else 0.0,phi)
