def fwd_eck2(op,lam,phi,lam_abs):
    a=op.ell.a*op.k0
    s=abs(math.sin(phi))
    root=math.sqrt(max(0,4-3*s))
    x=2*a*lam*math.sqrt((4-3*s)/(6*math.pi))
