    B=math.sqrt(2*math.pi/3)
    root=2-abs(y)/(a*B) if a!=0 else 2
    if root<1 or root>2: raise CoordError()
    s=(4-root*root)/3
    phi=math.copysign(math.asin(max(0,min(1,s))),y)
