import math,subprocess
lats=[i*5 for i in range(19)]
inp=''.join(f"57.29577951308232 {lat}\n" for lat in lats)
p=subprocess.run(["./executable",f"+proj=natearth2","+R=1","-f","%.15f"],input=inp.encode(),capture_output=True)
vals=[tuple(map(float,l.split())) for l in p.stdout.decode().splitlines()]

def fit(targetfn,deg):
 m=deg+1;A=[[0]*m for _ in range(m)];b=[0]*m
 for lat,(x,y) in zip(lats,vals):
  if lat==0 and targetfn=='y':continue
  phi=math.radians(lat);row=[phi**(2*i) for i in range(m)];target=x if targetfn=='x' else y/phi
  for i in range(m):
   b[i]+=row[i]*target
   for j in range(m):A[i][j]+=row[i]*row[j]
 M=[row[:]+[b[i]] for i,row in enumerate(A)]
 for i in range(m):
  piv=max(range(i,m),key=lambda r:abs(M[r][i]));M[i],M[piv]=M[piv],M[i];d=M[i][i]
  for j in range(i,m+1):M[i][j]/=d
  for k in range(m):
   if k!=i:
    f=M[k][i]
    for j in range(i,m+1):M[k][j]-=f*M[i][j]
 c=[M[i][m] for i in range(m)];err=0
 for lat,(x,y) in zip(lats,vals):
  phi=math.radians(lat);pred=sum(c[i]*phi**(2*i) for i in range(m));target=x if targetfn=='x' else (y/phi if phi else c[0]);err=max(err,abs(pred-target))
 print(targetfn,deg,c,err)
for deg in range(2,9):fit('x',deg)
for deg in range(2,9):fit('y',deg)
