# Fahey and Loximuthal
def fwd_fahey(op,lam,phi,lam_abs):
    a=op.ell.a*op.k0
    cb=math.cos(math.radians(35.0))
    t=math.tan(phi/2)
    if abs(t)>1: raise CoordError()
    return (a*lam*cb*math.sqrt(max(0,1-t*t)), a*(1+cb)*t)
def inv_fahey(op,x,y):
    a=op.ell.a*op.k0;cb=math.cos(math.radians(35.0))
    phi=2*math.atan(y/(a*(1+cb)))
    den=a*cb*math.sqrt(max(0,1-math.tan(phi/2)**2))
    return (x/den if den else 0.0,phi)
reg("fahey",fwd_fahey,inv_fahey)

def setup_loxim(op):
    op._lox_phi1=op.params.get_angle("lat_1",0.0) if op.params.has("lat_1") else 0.0
def _psi_sph(phi):
    return math.atanh(max(-0.9999999999999999,min(0.9999999999999999,math.sin(phi)))) if abs(phi)<math.pi/2 else math.copysign(math.inf,phi)
def fwd_loxim(op,lam,phi,lam_abs):
    a=op.ell.a*op.k0; phi1=op._lox_phi1
    if abs(phi-phi1)<1e-12:
        x=a*lam*math.cos(phi1)
    else:
        x=a*lam*(phi-phi1)/(_psi_sph(phi)-_psi_sph(phi1))
    return (x,a*(phi-phi1))
def inv_loxim(op,x,y):
    a=op.ell.a*op.k0; phi1=op._lox_phi1; phi=y/a+phi1
    if abs(phi-phi1)<1e-12:
        lam=x/(a*math.cos(phi1))
    else:
        lam=x*(_psi_sph(phi)-_psi_sph(phi1))/(a*(phi-phi1))
    return (lam,phi)
reg("loxim",fwd_loxim,inv_loxim,setup_loxim)
