# Mollweide-like theta models
def _theta_model_fwd(op,lam,phi,Cx,Cy,K):
    a=op.ell.a*op.k0
    target=K*math.sin(phi)
    def f(th): return (2*th+math.sin(2*th)-target,2+2*math.cos(2*th))
    theta=_newton_theta(phi,f)
    return (a*Cx*lam*math.cos(theta),a*Cy*math.sin(theta))
def _theta_model_inv(op,x,y,Cx,Cy,K):
    a=op.ell.a*op.k0
    s=y/(a*Cy)
    if abs(s)>1: raise CoordError()
    theta=math.asin(s)
    sinphi=(2*theta+math.sin(2*theta))/K
    if abs(sinphi)>1: raise CoordError()
    phi=math.asin(sinphi)
    den=a*Cx*math.cos(theta)
    return (x/den if den else 0.0,phi)

def fwd_wag4(op,lam,phi,lam_abs):
    Cx=0.863095139886
    K=2*(math.pi/3)+math.sin(2*math.pi/3)
    Cy=4/(Cx*K)
    return _theta_model_fwd(op,lam,phi,Cx,Cy,K)
def inv_wag4(op,x,y):
    Cx=0.863095139886;K=2*(math.pi/3)+math.sin(2*math.pi/3);Cy=4/(Cx*K)
    return _theta_model_inv(op,x,y,Cx,Cy,K)
reg("wag4",fwd_wag4,inv_wag4)

