# Globular projections
def _meridian_circle_x(lam,Y0):
    Rmap=math.pi/2
    if lam==0: return 0.0
    h=(lam*lam-Rmap*Rmap)/(2*lam)
    rad=abs(lam-h)
    if rad*rad < Y0*Y0: raise CoordError()
    return h + math.copysign(math.sqrt(rad*rad-Y0*Y0),lam-h)
def fwd_apian(op,lam,phi,lam_abs):
    a=op.ell.a*op.k0
    return (a*_meridian_circle_x(lam,phi),a*phi)
reg("apian",fwd_apian,lambda op,x,y: op.numeric_inverse(x,y))
reg("ortel",fwd_apian,lambda op,x,y: op.numeric_inverse(x,y))
def fwd_bacon(op,lam,phi,lam_abs):
    a=op.ell.a*op.k0
    Y0=(math.pi/2)*math.sin(phi)
    return (a*_meridian_circle_x(lam,Y0),a*Y0)
reg("bacon",fwd_bacon,lambda op,x,y: op.numeric_inverse(x,y))

def fwd_nicol(op,lam,phi,lam_abs):
    a=op.ell.a*op.k0
    Rmap=math.pi/2
    if lam==0:
        return (0.0,a*phi)
    if phi==0:
        return (a*lam,0.0)
    if abs(abs(lam)-math.pi/2)<1e-12:
        return (a*lam*math.cos(phi),a*Rmap*math.sin(phi))
    h=(lam*lam-Rmap*Rmap)/(2*lam)
    r1=abs(lam-h)
    # parallel circle centre k
    denom=(2*phi-math.pi*math.sin(phi))
    if abs(denom)<1e-15:
        k=0.0
    else:
        k=(phi*phi-Rmap*Rmap)/denom
    r2=abs(phi-k)
    C1=(h,0.0); C2=(0.0,k)
    dx=C2[0]-C1[0]; dy=C2[1]-C1[1]; d=math.hypot(dx,dy)
    if d==0: raise CoordError()
    aa=(r1*r1-r2*r2+d*d)/(2*d)
    hh2=r1*r1-aa*aa
    if hh2< -1e-12: raise CoordError()
    hh=math.sqrt(max(0,hh2))
    xm=C1[0]+aa*dx/d; ym=C1[1]+aa*dy/d
    rx=-dy*hh/d; ry=dx*hh/d
    cand1=(xm+rx,ym+ry); cand2=(xm-rx,ym-ry)
    # choose candidate close to approx (lam cosphi, phi)
    approx=(lam*math.cos(phi),phi)
    def dist(c): return (c[0]-approx[0])**2+(c[1]-approx[1])**2
    X,Y=cand1 if dist(cand1)<=dist(cand2) else cand2
    return (a*X,a*Y)
reg("nicol",fwd_nicol,lambda op,x,y: op.numeric_inverse(x,y))
