sys.path.insert(0,'/tmp');from fit import solve
pts=[(0,.74482),(15,.7411351899),(30,.7297265228),(45,.7094871823),(60,.6784439865),(75,.6336886555),(90,.57188)];A=.74482
# model ratio r=(1-B z)/(1+C z), z=t^2. Use 45,90 solve B,C: r+r C z+B z=1
for model in ['rat','sqrt']:
 sel=[pts[3],pts[6]];M=[];b=[]
 for lat,x in sel:
  z=math.tan(math.radians(lat)/2)**2;r=x/A
  if model=='rat':M.append([z,r*z]);b.append(1-r)
  else:
   # r=sqrt((1-Bz)/(1+Cz)) => r^2 + r^2 C z + B z=1
