import math,subprocess,importlib.util
spec=importlib.util.spec_from_file_location('p','proj.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
ell=m.Ellipsoid(*m.ELLIPSOIDS['GRS80'])
def trans(phi,kind):
 if kind=='geod':return phi
 if kind=='auth':return m.authalic_lat(phi,ell)
 if kind=='conf':return m.conformal_lat(phi,ell)
 if kind=='geoc':return math.atan((1-ell.es)*math.tan(phi))
 if kind=='rect':return m.meridional_arc(phi,ell)/m.meridional_arc(math.pi/2,ell)*math.pi/2
def radius(kind,phi0,tkind):
 s=math.sin(phi0);N=ell.a/math.sqrt(1-ell.es*s*s);M=ell.a*(1-ell.es)/((1-ell.es*s*s)**1.5)
 if kind=='a':return ell.a
 if kind=='Rq': 
  e=ell.e;qp=(1-ell.es)*(1/(1-ell.es)-(1/(2*e))*math.log((1-e)/(1+e)));return ell.a*math.sqrt(qp/2)
 if kind=='gauss':return math.sqrt(M*N)
 if kind=='N':return N
 if kind=='M':return M
 if kind=='Ncos':return N*math.cos(phi0)/math.cos(trans(phi0,tkind))
pts=[]
for lat0,lon0 in [(0,0),(45,10),(20,5)]:
 for lon,lat in [(lon0+2,lat0+5),(lon0+10,lat0+10),(lon0-5,lat0-10)]:
  p=subprocess.run(['./executable','+proj=gnom',f'+lat_0={lat0}',f'+lon_0={lon0}'],input=f"{lon} {lat}\n".encode(),capture_output=True)
  if p.stdout and b'*' not in p.stdout:
   x,y=map(float,p.stdout.split());pts.append((lon,lat,lon0,lat0,x,y))
for tk in ['geod','auth','conf','geoc','rect']:
 for rk in ['a','Rq','gauss','N','M','Ncos']:
  errs=[]
  for lon,lat,lon0,lat0,xr,yr in pts:
   phi=trans(math.radians(lat),tk);phi0=trans(math.radians(lat0),tk);lam=math.radians(lon-lon0);R=radius(rk,math.radians(lat0),tk)
   den=math.sin(phi0)*math.sin(phi)+math.cos(phi0)*math.cos(phi)*math.cos(lam);x=R*math.cos(phi)*math.sin(lam)/den;y=R*(math.cos(phi0)*math.sin(phi)-math.sin(phi0)*math.cos(phi)*math.cos(lam))/den;errs.append(max(abs(x-xr),abs(y-yr)))
  print(tk,rk,'max',max(errs),'rms',math.sqrt(sum(e*e for e in errs)/len(errs)))
