spec=importlib.util.spec_from_file_location('p','proj.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);ell=m.Ellipsoid(*m.ELLIPSOIDS['GRS80'])
def unit_ecef(lon,lat):
 lam=math.radians(lon);phi=math.radians(lat);N=ell.a/math.sqrt(1-ell.es*math.sin(phi)**2);v=(N*math.cos(phi)*math.cos(lam),N*math.cos(phi)*math.sin(lam),N*(1-ell.es)*math.sin(phi));n=math.sqrt(sum(x*x for x in v));return tuple(x/n for x in v)
errs=[]
for lat0,lon0 in [(0,0),(45,10),(20,5)]:
 for lon,lat in [(lon0+2,lat0+5),(lon0+10,lat0+10),(lon0-5,lat0-10)]:
  p=subprocess.run(['./executable','+proj=gnom',f'+lat_0={lat0}',f'+lon_0={lon0}'],input=f"{lon} {lat}\n".encode(),capture_output=True);xr,yr=map(float,p.stdout.split())
