import subprocess
meta=[l.split(' :')[0] for l in open('/tmp/harvest/list_p.txt')]
extra={p:['+lat_1=30','+lat_2=60'] for p in ['euler','murd1','murd2','murd3','tissot','vitk1','pconic','lcc','aea','eqdc']}
extra.update({p:['+lat_1=45'] for p in ['bonne','ccon','leac','imw_p']})
extra['geos']=['+h=35785831'];extra['nsper']=['+h=1000000'];extra['tpers']=['+h=1000000'];extra['tpeqd']=['+lat_1=45','+lon_1=0','+lat_2=45','+lon_2=10'];extra['gn_sinu']=['+m=2','+n=3'];extra['urm5']=['+n=0.5'];extra['urmfps']=['+n=0.5'];extra['chamb']=['+lat_1=0','+lon_1=0','+lat_2=30','+lon_2=30','+lat_3=60','+lon_3=0'];extra['oea']=['+n=2','+m=1','+theta=30'];extra['lsat']=['+lsat=1','+path=1'];extra['misrsom']=['+path=1']
noinv=[];hasinv=[];unknown=[]
for p in meta:
 args=['-I',f'+proj={p}']+extra.get(p,[])
 r=subprocess.run(['./executable']+args,input=b'1000 1000\n',capture_output=True)
 if b'inverse projection not available' in r.stderr:noinv.append(p)
 elif r.returncode!=0:unknown.append((p,r.returncode,r.stderr[:80]))
 else:hasinv.append(p)
print('NOINV',noinv)
print('UNKNOWN',unknown)
print('HAS count',len(hasinv))
